INSERT INTO dbo.Tenants (Name, Description, Alias, Settings, Remarks, IsActive, IsDeleted, AddedBy, AddedOn)
SELECT v.Name, v.Description, v.Alias, v.Settings, v.Remarks, v.IsActive, v.IsDeleted, v.AddedBy, GETDATE() AS AddedOn
FROM (VALUES
    ('Identity', 'A aplicação Identity é um cliente do próprio sistema de autenticação e autorização, utilizando os recursos, ações, papéis e permissões para gerenciar o acesso dos usuários à própria aplicação.', 'Identity', NULL, NULL, 1, 0, 1),
	('eFLOW', 'Business Process Management', 'eFLOW', NULL, NULL, 1, 0, 1)
) AS v
(Name, Description, Alias, Settings, Remarks, IsActive, IsDeleted, AddedBy)
WHERE NOT EXISTS
(
    SELECT 1
    FROM dbo.Tenants t
    WHERE t.Name = v.Name AND t.Alias = v.Alias
);
GO
EXEC sp_set_session_context @key=N'IsSuperAdmin', @value=1;
INSERT INTO dbo.Apps (TenantId, Name, Description, IsActive, IsDeleted, AddedBy, AddedOn)
SELECT v.TenantId, v.Name, v.Description, v.IsActive, v.IsDeleted, v.AddedBy, SYSDATETIME() AS AddedOn
FROM (VALUES
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'),  'Identity', 'Identity é um sistema de autenticação e autorização que permite gerenciar usuários, papéis, recursos e permissões de forma segura e eficiente.', 1, 0, NULL, 1 ),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'),  'PDF Operations', 'Aplicação relacionada com operações sobre ficheiros PDF, como substituição de páginas, extração de páginas, etc.', 1, 0, NULL, 1 )
) AS v
(TenantId, Name, Description, IsActive, IsDeleted, Remarks, AddedBy)
WHERE NOT EXISTS
(
    SELECT 1
    FROM dbo.Apps a
    WHERE a.TenantId = v.TenantId
      AND a.Name = v.Name 
);
GO
