INSERT INTO dbo.Roles (TenantId, AppId, Name, Description, IsActive, IsDeleted, AddedBy, AddedOn)
SELECT v.TenantId, v.AppId, v.Name, v.Description, v.IsActive, v.IsDeleted, v.AddedBy, GETDATE() AS AddedOn
FROM (VALUES
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'BackOffice', 'Perfil de suporte interno responsável por rotinas administrativas/operacionais do sistema (cadastros, parametrizações, atendimento e ajustes), geralmente sem poder total de governança.', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'Admin', 'Perfil com permissões máximas para configurar o sistema/tenant, gerenciar usuários, roles, permissões, integrações e parâmetros críticos.', 1, 0, 1),

    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'BackOffice', 'Perfil de suporte interno responsável por rotinas administrativas/operacionais do sistema (cadastros, parametrizações, atendimento e ajustes), geralmente sem poder total de governança.', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Admin', 'Perfil com permissões máximas para configurar o sistema/tenant, gerenciar usuários, roles, permissões, integrações e parâmetros críticos.', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Gestor', 'Perfil de gestão da área; acompanha indicadores e resultados, aprova decisões/processos sob sua responsabilidade e define prioridades/equipes (com menos poderes técnicos que o Admin).', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Supervisor', 'Perfil de liderança operacional; distribui e monitora trabalho, valida execuções, trata exceções e garante cumprimento de regras e SLAs.', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Operador', 'Perfil de execução; realiza as atividades do dia a dia (registrar, tratar e concluir tarefas/processos) dentro das permissões do seu escopo.', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Auditor', 'Perfil de consulta e verificação; acesso predominantemente de leitura para relatórios, trilhas de auditoria e evidências, sem permissão para alterar dados/processos.', 1, 0, 1)
) AS v
(TenantId, AppId, Name, Description, IsActive, IsDeleted, AddedBy)
WHERE NOT EXISTS
(
    SELECT 1
    FROM dbo.Roles t
    WHERE t.TenantId = v.TenantId
	  and t.AppId = v.AppId
	  and t.Name = v.Name
);
