	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Read', 'Permite visualizar e consultar informações e detalhes de registros, sem realizar alterações.', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Update', 'Permite editar/atualizar registros existentes (dados, status, configurações, anexos, etc.).', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Delete', 'Permite excluir registros (remoção definitiva ou “soft delete”, conforme a regra do sistema).', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Export', 'Permite gerar e baixar dados/relatórios para formatos externos (ex.: CSV, Excel, PDF) ou enviar para integração.', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Approve', 'Permite aprovar uma solicitação/etapa de processo, liberando a próxima fase do fluxo.', 1, 0, 1),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'Send', 'Permite enviar informações/itens para alguém ou para outro sistema (ex.: encaminhar tarefa, disparar notificação, submeter para análise).', 1, 0, 1)
