INSERT INTO dbo.Resources
(TenantId, AppId, Name, Description, IsActive, IsDeleted, AddedBy, AddedOn, ModifiedBy, ModifiedAt)
SELECT v.TenantId, v.AppId, v.Name, v.Description, v.IsActive, v.IsDeleted, v.AddedBy, GETDATE() AS AddedOn, v.ModifiedBy, v.ModifiedAt
FROM (VALUES
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'Tenants'        , 'Tenants são responsáveis por armazenar as informações dos tenants (clientes) que utilizam o sistema de autenticação e autorização.', 1, 0, 1, NULL, NULL),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'Apps'           , 'Apps são responsáveis por armazenar as informações das aplicações de cada tenant.', 1, 0, 1, NULL, NULL),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'Users'          , 'Users são responsáveis por armazenar as informações das aplicações de cada tenant.', 1, 0, 1, NULL, NULL),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'Roles'          , 'Roles são responsáveis por armazenar as informações dos papéis de cada tenant e aplicação.', 1, 0, 1, NULL, NULL),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'Resources'      , 'Resources são responsáveis por armazenar as informações dos recursos de cada aplicação do tenant.', 1, 0, 1, NULL, NULL),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'Actions'        , 'Actions são responsáveis por armazenar as informações das ações de cada aplicação do tenant.', 1, 0, 1, NULL, NULL),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'RolePermissions', 'RolePermissions são responsáveis por armazenar as permissões de cada papel dentro de uma aplicação do tenant.', 1, 0, 1, NULL, NULL),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'UserRoles'      , 'UserRoles são responsáveis por armazenar os papéis atribuídos a cada usuário dentro de uma aplicação do tenant.', 1, 0, 1, NULL, NULL),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'RefreshTokens'  , 'RefreshTokens são responsáveis por armazenar os tokens de atualização para cada usuário dentro de uma aplicação do tenant.', 1, 0, 1, NULL, NULL),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'JwtKeys'        , 'JwtKeys são responsáveis por armazenar as chaves JWT para cada tenant, utilizadas para assinatura de tokens JWT.', 1, 0, 1, NULL, NULL),
	((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'Identity'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'Identity'), 'JobDefinitions' , 'JobDefinitions são responsáveis por armazenar as definições de jobs para cada tenant, utilizada para configurar jobs do Hangfire.', 1, 0, 1, NULL, NULL),

    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'ReplacePage'      , 'Replaces a specific page in a target PDF document with another page provided as a byte array.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'ConvertDocEmlToPdf', 'Converts a document in EML format (email) represented as a byte array into a PDF document.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'ConvertImageToPdf', 'Converts an image represented as a byte array into a PDF document.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'ConvertHtmlToPdf' , 'Converts HTML content to PDF format using PuppeteerSharp, which is a .NET port of the popular Node.js library Puppeteer.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'ExtractRange'     , 'Extracts a specified range of pages from a PDF document represented as a byte array.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'ExtractPages'     , 'Extracts specific pages from a PDF document represented as a byte array based on a list of page numbers.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'GetNumberOfPages' , 'Gets the number of pages in a PDF document represented as a byte array.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'GetQRData'        , 'QRData represents the information extracted from a QR code found within a PDF document.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'MergePdfs'        , 'Merges multiple PDF documents represented as byte arrays into a single PDF document.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'MergePdfSharp'    , 'Asynchronously merges multiple PDF documents into a single PDF file.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'ReplacePagePdf'   , 'Replaces a specific page in a target PDF document with another page provided as a byte array.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'SeparatePdfPages' , 'Separates each page of a PDF document represented as a byte array into individual PDF documents, returning a list of byte arrays where each byte array corresponds to a single page from the original PDF.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'TranscodePdf'     , 'Transcodes a PDF document represented as a byte array using the QPdfSharp library.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'TranscodePdfPig'  , 'Transcodes a PDF document represented as a byte array using the PdfPig library.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'IsProtectPdf'     , 'IsProtectPdfAsync is a method that checks if a given PDF document, represented as a byte array, is protected.', 1, 0, 1, NULL, NULL),
    ((SELECT TOP (1) t.Id FROM dbo.Tenants t WHERE t.Name = 'eFLOW'), (SELECT TOP (1) t.Id FROM dbo.Apps t WHERE t.Name = 'PDF Operations'), 'IsValidPdf'       , 'IsValidPdfAsync is a method that checks if a given PDF document, represented as a byte array, is valid.', 1, 0, 1, NULL, NULL)
) AS v
(TenantId, AppId, Name, Description, IsActive, IsDeleted, AddedBy, ModifiedBy, ModifiedAt)
WHERE NOT EXISTS
(
    SELECT 1
    FROM dbo.Resources a
    WHERE a.TenantId = v.TenantId
	  AND a.AppId = v.AppId
      AND a.Name = v.Name
);
